solution.code:
#include <stdio.h>

int main() {
    int a[] = {4, 0, 5, 0, 0, 6};
    int n = 6;
    int pos = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] != 0) {
            a[pos++] = a[i];
        }
    }
    while (pos < n) {
        a[pos++] = 0;
    }
    for (int i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
